the comparison by value is fine for now, but if the struct introduces pointer objects it would fail.

```go
package main

import "fmt"

type bar struct { i int }
type foo struct { b *bar }

func main() {
	a := &foo{b: &bar{i: 10}}
	b := &foo{b: &bar{i: 10}}
	fmt.Printf("a == b = %v", *a == *b) // a == b = false
}
```

.Equal compares equality of the values, which may or may not be identical to struct equality, depending on normalization and whether the string rendering is cached

```go
func TestCPUComparison(t *testing.T) {
	l1 := ResourceList{"cpu": resource.MustParse("1m")}
	l2 := ResourceList{"cpu": resource.MustParse(".001")}

	cpu1 := l1.Cpu()
	cpu2 := l2.Cpu()

	t.Logf("%#v", cpu1)
	t.Logf("%#v", cpu2)

	if cpu1.Equal(*cpu2) {
		t.Log("passed Equal()")
	} else {
		t.Fatal("failed Equal()")
	}

	if *cpu1 == *cpu2 {
		t.Log("passed ==")
	} else {
		t.Fatal("failed ==")
	}
}
```

